def schuldrechtliche_sondergrundfrist(fristfall=None, ereignis_am=None, einordnungsnachweis=None):
    """Berechnet die gesetzliche Standarddauer für den ausdrücklich qualifizierten Fristfall."""
    _auswahl(fristfall, 'fristfall', tuple(_FAELLE))
    _datum(ereignis_am, 'ereignis_am')
    _text(einordnungsnachweis, 'einordnungsnachweis')
    anzahl, einheit, fallhinweis = _FAELLE[fristfall]
    ende = _frist(ereignis_am, anzahl, einheit, 'ereignis')
    eingaben = dict(fristfall=fristfall, ereignis_am=ereignis_am, einordnungsnachweis=einordnungsnachweis)
    ergebnis = _ergebnis(dict(rechnerisches_fristende=ende.isoformat()), 'datum', 'BGB_SCHULDRECHTLICHE_SONDERGRUNDFRIST', eingaben, [dict(operation='Gesetzliche Dauer nach Fristfall auswählen und Ereignisfrist mit vorhandenem Kalenderkern berechnen')], eingaben.copy())
    ergebnis['annahmen'] = ['Rechtlich maßgeblicher Fristfall und Ereignistag sowie ausschließliche Anwendung der gesetzlichen Standarddauer qualifiziert; feste lokale BGB-Fassung.']
    ergebnis['hinweise'] = ['Nur rechnerische gesetzliche Grundfrist mit Ereignisbeginn; keine automatische Feiertags-/Hemmungs-/sonstige Fristkorrektur. Fristende bezeichnet den letzten eingeschlossenen Tag bis Tagesablauf; rechtzeitige Handlungen am Endtag bleiben möglich. Qualifizierte Normvoraussetzungen und abweichende Sonderregeln vor Nutzung bestimmen.', fallhinweis]
    return ergebnis
